import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/admin-season-settings-after-generation.BDcipNtS.js";import"./chunks/booker-season-detail._iJaKv5g.js";import"./chunks/player-season-summary.CuhjbTQy.js";var i=JSON.parse(`{"title":"Run a Season","description":"","frontmatter":{},"headers":[],"relativePath":"guide/run-a-season.md","filePath":"guide/run-a-season.md"}`),a={name:`guide/run-a-season.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="run-a-season" tabindex="-1">Run a Season <a class="header-anchor" href="#run-a-season" aria-label="Permalink to &quot;Run a Season&quot;">​</a></h1><p>A booker&#39;s guide to seasons — the yearly frame that groups shows, awards, and wrestler histories into chapters you can look back on.</p><p><strong>What a season gives you:</strong> a container for your promotion&#39;s year (its shows, its champions, its milestones), per-wrestler season histories for the record books, and an auto-generated show schedule so the calendar fills itself.</p><hr><h2 id="step-1-—-create-the-season" tabindex="-1">Step 1 — Create the season <a class="header-anchor" href="#step-1-—-create-the-season" aria-label="Permalink to &quot;Step 1 — Create the season&quot;">​</a></h2><p>Open <strong>Season List</strong> from the navigation and click <strong>Add Season</strong>. Give it a name (and the year or episode numbering your promotion uses). The season starts as the <strong>active season</strong> — new shows you create default into it.</p><p><img src="/screenshots/booker-season-list.png" alt="Season list"></p><hr><h2 id="step-2-—-generate-the-schedule-optional-but-recommended" tabindex="-1">Step 2 — Generate the schedule (optional but recommended) <a class="header-anchor" href="#step-2-—-generate-the-schedule-optional-but-recommended" aria-label="Permalink to &quot;Step 2 — Generate the schedule (optional but recommended)&quot;">​</a></h2><p>Under <strong>Season Settings</strong>, the <strong>Generate Season Schedule</strong> button builds a season&#39;s worth of shows automatically:</p><ol><li>Open <strong>Season Settings</strong> and click <strong>Generate Season Schedule</strong>.</li><li>The game lays out the season&#39;s shows — weekly TV, premium live events — as <strong>Scheduled</strong> entries on the calendar, following your show templates.</li><li>Confirm when prompted; the settings page shows the schedule before and after.</li></ol><p><img src="/screenshots/admin-season-settings-after-generation.png" alt="Season settings — after generation"></p><p>Generate early: tournaments with a <strong>Host Show</strong> binding and annual editions pace their rounds against upcoming shows, so a full calendar gives them somewhere to land.</p><hr><h2 id="step-3-—-run-the-shows" tabindex="-1">Step 3 — Run the shows <a class="header-anchor" href="#step-3-—-run-the-shows" aria-label="Permalink to &quot;Step 3 — Run the shows&quot;">​</a></h2><p>The season now runs exactly like normal booking — see <a href="./schedule-a-show.html">Schedule a Show</a> for the per-show loop. Season membership is automatic: shows created while a season is active belong to it, and their results feed the season&#39;s story.</p><p>As the season progresses:</p><ul><li><strong>Wrestler snapshots</strong> record each wrestler&#39;s fan count at season start — the baseline for season-end awards and historical performance.</li><li><strong>Season awards</strong> accrue on the season&#39;s detail page as milestones are hit.</li></ul><p><img src="/screenshots/booker-season-detail.png" alt="Season detail"></p><hr><h2 id="step-4-—-read-the-record-books" tabindex="-1">Step 4 — Read the record books <a class="header-anchor" href="#step-4-—-read-the-record-books" aria-label="Permalink to &quot;Step 4 — Read the record books&quot;">​</a></h2><p>Two places tell the season&#39;s story after the fact:</p><ul><li><strong>Season Detail</strong> — the season&#39;s awards and achievements with dates.</li><li><strong>Player Dashboard</strong> — each player-controlled wrestler&#39;s <strong>season history</strong> and <strong>season summary</strong> (start vs end fans, peak moments), so players see their own arc across the year.</li></ul><p><img src="/screenshots/player-season-summary.png" alt="Season summary"></p><hr><h2 id="step-5-—-close-it-out-and-start-the-next" tabindex="-1">Step 5 — Close it out and start the next <a class="header-anchor" href="#step-5-—-close-it-out-and-start-the-next" aria-label="Permalink to &quot;Step 5 — Close it out and start the next&quot;">​</a></h2><p>When the season&#39;s calendar is exhausted, create the next season and it becomes active — previous seasons stay browsable in the Season List with everything attached.</p><blockquote><p>💡 <strong>Seasons and universes:</strong> seasons belong to your universe&#39;s continuity. If you run several universes (see <a href="./manage-universes.html">Manage Universes</a>), each keeps its own seasons.</p></blockquote><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./schedule-a-show.html">Schedule a Show</a> — the weekly loop inside the season.</li><li><a href="./configure-tournaments.html">Configure Tournaments</a> — brackets that pace against the season&#39;s calendar.</li><li>The auto-generated <a href="./season-management.html">Season Management</a> guide documents every season screen.</li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};